 "content": "def transform(grid):
    """Overlay the connected marker motif onto matching background regions."""
    from collections import Counter, deque
    h, w = len(grid), len(grid[0])
    counts = Counter(v for row in grid for v in row)
    marker = min((v for v in counts if v != 0), key=lambda v: counts[v])
    background = max((v for v in counts if v != marker), key=lambda v: counts[v])
    # Select largest connected marker component as the motif.
    seen = set(); components = []
    for r in range(h):
        for c in range(w):
            if grid[r][c] != marker or (r,c) in seen: continue
            q=deque([(r,c)]); seen.add((r,c)); comp=[]
            while q:
                y,x=q.popleft(); comp.append((y,x))
                for dy,dx in ((1,0),(-1,0),(0,1),(0,-1)):
                    p=(y+dy,x+dx)
                    if 0<=p[0]<h and 0<=p[1]<w and p not in seen and grid[p[0]][p[1]]==marker:
