            components.append(comp)
    motif=max(components,key=len)
    rmin=min(r for r,c in motif); cmin=min(c for r,c in motif)
    shape={(r-rmin,c-cmin) for r,c in motif}
    mh=max(r for r,c in shape)+1; mw=max(c for r,c in shape)+1
    out=[row[:] for row in grid]
    for r0 in range(h-mh+1):
        for c0 in range(w-mw+1):
            if all(grid[r0+dr][c0+dc]==background for dr,dc in shape):
                for dr,dc in shape: out[r0+dr][c0+dc]=marker
    return out
